import{_ as a}from"./chunks/voxel_map_collision.DAUbGWHX.js";import{_ as o,o as l,c as i,a5 as s}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Server Example: Voxel Map Collision","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/voxel_map_collision.md","filePath":"sections/examples/server/voxel_map_collision.md"}'),r={name:"sections/examples/server/voxel_map_collision.md"};function t(n,e,c,d,h,p){return l(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="server-example-voxel-map-collision" tabindex="-1">Server Example: Voxel Map Collision <a class="header-anchor" href="#server-example-voxel-map-collision" aria-label="Permalink to &quot;Server Example: Voxel Map Collision&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Drops spheres, boxes, capsules, cylinders, convex meshes and triangle meshes onto a voxel playground with stairs down into a pit, a wall with windows, pillars and rubble, while new craters are carved into the floor. Use <code>rayrai_tcp_viewer</code> for supported visualization.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+a+'" alt="voxel_map_collision example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>voxel_map_collision</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/voxel_map_collision</span></span></code></pre></div><p>On Windows, run <code>voxel_map_collision.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Builds a 12 m x 12 m map of 5 cm voxels on 3 m of ground, with a low rim around the edge, and shapes it with <code>VoxelMap::fillBox()</code>. The ground is deeper than a crater, since the map is empty below its domain.</li><li>Adds a new body every 0.3 s, cycling through every collision shape, until 120 bodies are in the scene. The convex meshes are the convex hull of the bundled <code>monkey/monkey.obj</code>; the triangle meshes are a U-shaped block and an arch (<code>rayrai/coacd</code>), collided face by face.</li><li>Every 8 s, <code>VoxelMap::fillSphere()</code> carves a new crater of radius 1 m into the floor, and the bodies on it fall in. Sleeping bodies wake when the voxels around them change.</li><li>See <a href="./../../VoxelMap.html">Voxel Map</a>.</li></ul>',13)])])}const v=o(r,[["render",t]]);export{u as __pageData,v as default};
